20	// buildApprovalRequest validates and constructs an approval request. A
21	// REQUEST_CHANGES decision requires a non-empty message; the server enforces
22	// this too, but a client-side check gives a clearer error before the round trip.
23	func buildApprovalRequest(event, message string) (api.TrailApprovalRequest, error) {
24		msg := strings.TrimSpace(message)
25		if event == "REQUEST_CHANGES" && msg == "" {
26			return api.TrailApprovalRequest{}, errors.New("--message is required when requesting changes")
27		}
28		return api.TrailApprovalRequest{Event: event, Body: msg}, nil
29	}
