31	// resolveNumberedTrail resolves a trail by optional selector, falling back to
32	// the current branch (or --branch), and requires it to have a number (the
33	// number-keyed subresource endpoints — approvals, threads — reject a trail
34	// without one).
35	func resolveNumberedTrail(ctx context.Context, client *api.Client, repoOverride, selector, branch string) (*api.TrailResource, string, string, string, error) {
36		forge, owner, repoName, err := resolveTrailRepoOrRemote(ctx, repoOverride)
37		if err != nil {
38			return nil, "", "", "", err
39		}
40		found, err := resolveTrailBySelector(ctx, client, forge, owner, repoName, selector, branch)
41		if err != nil {
42			return nil, "", "", "", err
43		}
44		if found.Number <= 0 {
45			return nil, "", "", "", errors.New("trail has no number yet")
46		}
47		return found, forge, owner, repoName, nil
48	}
