58	func submitTrailApproval(ctx context.Context, w, errW io.Writer, insecureHTTP bool, repoOverride, selector, branch, event, message, successVerb string) error {
59		if selector != "" && strings.TrimSpace(branch) != "" {
60			return errors.New("pass a trail selector or --branch, not both")
61		}
62		req, err := buildApprovalRequest(event, message)
63		if err != nil {
64			return err
65		}
66		// Auth/not-logged-in messages go to stderr; w carries command output only.
67		return runAuthenticatedTrailAPI(ctx, errW, insecureHTTP, repoOverride, func(ctx context.Context, client *api.Client) error {
68			found, forge, owner, repoName, err := resolveNumberedTrail(ctx, client, repoOverride, selector, branch)
69			if err != nil {
70				return err
71			}
