73			if err != nil {
74				return fmt.Errorf("failed to submit approval: %w", err)
75			}
76			defer resp.Body.Close()
77			if err := checkTrailResponse(resp); err != nil {
78				return err
79			}
80			var out api.TrailApprovalResponse
81			if err := api.DecodeJSON(resp, &out); err != nil {
82				return fmt.Errorf("failed to decode approval response: %w", err)
83			}
84			fmt.Fprintf(w, "%s trail #%d\n", successVerb, found.Number)
85			return nil
86		})
